/**
 * Badge: a short label for a status or a category.
 * Purpose: one place for badges. Generated by shadcn, then re-themed to Grove. Owner: design system.
 *   StatusBadge (S2-T05) maps domain statuses onto these tones; do not pick status colours elsewhere.
 * Props: tone ("neutral" default | "success" | "warning" | "danger" | "info" | "outline" |
 *   "featured" | "prime" | "budget"), dot (adds a status dot), asChild, native span props.
 * Responsive: 26 px tall, never wraps.
 * Accessibility: a status is always a word plus a dot or icon, never colour alone (R-DS-09).
 * States: none. Dependencies: cva, cn, radix Slot.
 * Tests: controls.test.tsx; Design Lab "Badges" (S2-T07).
 * UX reference: ds-components, Badges (c-core.css .badge).
 */
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

const badgeVariants = cva(
  "inline-flex h-(--size-badge) w-fit shrink-0 items-center gap-1 rounded-pill px-3 text-caption font-bold whitespace-nowrap [&_svg]:size-3.5 [&_svg]:shrink-0",
  {
    variants: {
      tone: {
        neutral: "bg-neutral-tint text-neutral",
        success: "bg-success-tint text-success",
        warning: "bg-warning-tint text-warning",
        danger: "bg-danger-tint text-danger",
        info: "bg-info-tint text-info",
        outline: "border border-line-strong bg-surface text-ink",
        featured: "bg-cta-tint text-cta-text",
        prime: "bg-ink text-on-primary",
        budget: "bg-primary-tint text-primary",
      },
      dot: {
        true: "before:size-1.75 before:shrink-0 before:rounded-pill before:bg-current before:content-['']",
        false: "",
      },
    },
    defaultVariants: { tone: "neutral", dot: false },
  },
);

type BadgeProps = Omit<ComponentProps<"span">, "ref"> &
  VariantProps<typeof badgeVariants> & { asChild?: boolean };

function Badge({ className, tone, dot, asChild = false, ...props }: BadgeProps) {
  const Component = asChild ? Slot.Root : "span";
  return (
    <Component
      data-slot="badge"
      className={cn(badgeVariants({ tone, dot }), className)}
      {...props}
    />
  );
}

export { Badge, badgeVariants };
